const lesson = (id, order, title, content) => ({
  id,
  subjectId: 'digital_electronics',
  order,
  totalModules: 13,
  title,
  estimatedTime: '45 mins',
  ...content
});

const interview = (question, answer) => ({ question, answer });
const mcq = (question, options, correctAnswer, explanation) => ({ question, options, correctAnswer, explanation });
const equation = (equation, description) => ({ equation, description });
const numerical = (problem, solution) => ({ problem, solution });
const truthTable = (title, columns, rows) => ({ title, columns, rows });

export const DIGITAL_ELECTRONICS_MODULE_ORDER = [
  'number-systems', 'boolean-algebra', 'logic-gates', 'k-maps',
  'combinational-circuits', 'multiplexers', 'demultiplexers', 'encoders',
  'decoders', 'flip-flops', 'counters', 'registers', 'memory'
];

