    booleanExpressions: [{ expression: 'NAND(A,B)=(AB)\'', description: 'Inverted AND.' }, { expression: 'XOR=A\'B+AB\'', description: 'Two-input inequality detector.' }, { expression: 'XNOR=AB+A\'B\'', description: 'Two-input equality detector.' }],
    stepByStepExamples: [{ title: 'Implement XOR with basic gates', steps: ['Identify rows 01 and 10 as output 1.', 'Write minterms A\'B and AB\'.', 'OR the product terms: Y=A\'B+AB\'.', 'Alternatively use four NAND gates or a dedicated XOR cell.', 'Check the truth table and propagation paths.'] }],
    importantEquations: [equation('AND: Y=AB; OR: Y=A+B; NOT: Y=A\'', 'Two-state Boolean definitions.'), equation('NAND: Y=(AB)\'; NOR: Y=(A+B)\'', 'Universal inverted gates.'), equation('XOR: Y=A\'B+AB\'', 'One for unequal two-input values.'), equation('XNOR: Y=AB+A\'B\'', 'One for equal two-input values.'), equation('tPD = t(output threshold) - t(input threshold)', 'Propagation delay in seconds; threshold convention is specified by the logic family.')],
    numericalProblems: [numerical('A three-input AND gate receives 1,1,0. Find Y.', 'Y=1*1*0=0; every input must be high.'), numerical('An XOR chain receives A=1, B=0, C=1 using cascaded two-input XOR gates. Find output.', '1 XOR 0=1, then 1 XOR 1=0. XOR is 1 for an odd number of ones; two ones is even, so output 0.'), numerical('A path has three gate delays of 4 ns, 7 ns, and 5 ns. Estimate worst-case combinational path delay.', 'For a serial path, delays add: 4+7+5=16 ns, excluding wire, load, and setup margins.')],
    applications: ['Parity generation/checking with XOR.', 'Equality comparison with XNOR.', 'Control and datapath implementation in processors and controllers.'],
    advantages: ['Simple functional building blocks with well-defined truth tables.', 'NAND/NOR allow implementation with a single gate type.'],
